-- SPeditor — the guides of the editor itself (Help → How to use, cl_ui_guide.lua).
-- The guides of SAeditor are in its own folder (cl_saeditor_guides.lua).
local UI = SPeditor.UI
local C  = SPeditor.Client
local L  = SPeditor.L

